## 3.2.5. Using the ErrorBoundary Component

The `ErrorBoundary` component is a convenient way to handle errors in your application. It wraps around any components that may throw an error and handles it for you. You can use it as follows:

1.  Create a new file called `ErrorBoundary.tsx`.
2.  Add the following code to the file:

    ```
    import { ErrorBoundary } from 'react-error-boundary';

    export default function ErrorBoundary({ children }: {
      children?: ReactNode;
    }) {
      return <ErrorBoundary FallbackComponent={Fallback} />;
    }
    ```

3.  Replace `Fallback` with your custom fallback component.
4.  Add the `ErrorBoundary` component to your root component:

    ```
    import ErrorBoundary from './ErrorBoundary';

    export default function App() {
      return (
        <ErrorBoundary>
          <Router />
        </ErrorBoundary>
      );
    }
    ```

5.  Create a new file called `Fallback.tsx`.
6.  Add the following code to the file:

    ```
    import { ErrorInfo, ErrorBoundaryProps } from 'react-error-boundary';

    export default function Fallback({ error }: ErrorBoundaryProps) {
      return (
        <div>
          <h1>{error?.message}</h1>
          <pre style={{ whiteSpace: 'pre-wrap' }}>
            {error && JSON.stringify(error, null, 2)}
          </pre>
        </div>
      );
    }
    ```

