        {Number(page) > 1 ? (
          <Link href={`/deals?q=${q}&sort=${sort}&page=${Number(page) - 1}`}>
            <a
              className="text-gray-700 hover:underline"
            >
              Previous Page
            </a>
          </Link>
        ) : null}

        {/* Next button */}
        {Number(page) !== pages ? (
          <Link href={`/deals?q=${q}&sort=${sort}&page=${Number(page) + 1}`}>
            <a className="text-gray-700 hover:underline">Next Page</a>
          </Link>
        ) : null}

      </div>
    </div>
  )
}
