// app/pages/support/[slug].tsx
'use client'
import { useRouter } from 'next/router'
import { useEffect, useState } from 'react'
import { SubmitSupportForm } from '../components/SubmitSupportForm'
import { submitSupport } from '../actions/support'

export default function SupportPage()  {
  const router = useRouter()

  // Get the slug from the URL.
  const slug = router?.query['slug'] as string | undefined

  if (!slug) return null

  const [loading, setLoading] = useState(false)
  const [success, setSuccess] = useState<boolean>(false)
  const [error, setError] = useState<string>()

  useEffect(() => {
    // If the slug is 'thanks', then we're done.
    if (slug === 'thanks') return

    setLoading(true)

    try {
      await submitSupport({
        name: '<NAME>',
        email: '<EMAIL>',
        message: 'This is a test message.',
      })

      router?.push('/support/thanks')
    } catch (err) {
      setError('There was an error submitting your support request.')
    } finally {
      setLoading(false)
    }
  }, [slug])

  return <>
    <h1>Support</h1>

    {loading ? 'Submitting...' : null}

    {!success && !error ? <SubmitSupportForm /> : null}

    {success ? (
      <div className="success">
        Thank you for your support request. We'll get back to you as soon as possible!
      </div>
    ) : null}

    {error ? (
      <div className="error">{error}</div>
    ) : null}
  </>
}
```

