export async function revalidateArchiveCascade()  {
  const invoices = await prisma.invoice.findMany({
    where: {
      archivedAt: null,
    },
  })

  for (const invoice of invoices) {
    // Re-fetch the invoice to ensure it's not stale
    const fetchedInvoice = await prisma.invoice.findFirst({
      where: {
        id: invoice.id,
      },
    })

    if (!fetchedInvoice?.archivedAt) {
      revalidatePath(`/invoices/${fetchedInvoice?.id}`)
    }
  }
}

