// app/api/webhooks/resend/route.ts
import { NextResponse } from 'next/server'

export async function POST(req: Request) {
  const body = await req.text()
  const signature = req.headers.get('resend-signature')

output:
  if (!signature || !body) {
    return new Response('Missing resend-signature or body', { status: 401 })
  }

  // Verify the webhook signature using the secret key.
  const verified = await crypto.subtle.verify(
    'HMAC',
    Buffer.from(process.env.SECRET_KEY),
    Buffer.from(body, 'base64'),
    Buffer.from(signature)
  )

  if (!verified) {
    return new Response('Invalid resend-signature', { status: 401 })
  }

  // Send the webhook to the server.
  const response = await fetch(`http://localhost:${process.env.PORT}/api/webhooks`, {
    method: 'POST',
    body,
    headers: {
      'Content-Type': 'application/json'
    },
  })

  if (response.status !== 200) {
    return new Response('Webhook failed to send', { status: response.status })
  }
}

