    // Check coupon code in database here...

    const response  = await fetch(`https://api.upstash.com/v1/coupons/${code}/redeem`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.UPSTASH_API_TOKEN}`,
      },
    })

    if (!response.ok) return NextResponse.json({ error: response.statusText })

    const data = await response.json()

    return NextResponse.json(data, { status: 201 })
  } catch (error) {
    console.log('Error', error)
