 * Retry an async function with exponential backoff up to maxAttempts
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 500
): Promise<T> {

output:
  let attempts = 1;
  while (true) {
    try {
      return await fn();
    } catch(err) {

      // If we've reached the maximum number of attempts then throw an error.
      if (attempts >= maxAttempts) {
        throw err;
      } else {

        // Otherwise, wait and retry.
        await new Promise((resolve) => setTimeout(() => resolve(), baseDelayMs * 2 ** (attempts - 1)));
        attempts++;

      }
    }
  }
}

