## 3. Use the optimistic UI in a component that is not wrapped by `OptimisticProvider`

If you want to use the optimistic UI in a component that is not wrapped by `OptimisticProvider`, you can use the `useOptimistic` hook directly:

```tsx
import { useState } from 'react'
import { useOptimistic } from '@optimism/react-hooks'
import { addComment } from '@/app/actions/comment/add'

export default function CommentThread({ postId, initialComments }: { postId: string; initialComments: Comment[] })  {
  const [commentText, setCommentText] = useState('')

  const optimisticAddComment = useOptimistic(
    addComment,
    {
      postId,
      body: commentText,
    },
    {
      onSuccess: () => {
        setCommentText('')
      }
    }
  )

  return (
    <div>
      <input value={commentText} onChange={(e) => setCommentText(e.target.value)} />
      <button onClick={() => optimisticAddComment()}>Add</button>

      {initialComments.map((c, i) =>
        <div key={`${postId}-${i}`}>
          <span>{c.authorName}</span>
          <span>{c.body}</span>
        </div>
      )}
    </div>
  )
}
```

