// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private readonly _events = new Map<keyof E, Set<Function>>()

  on(event: keyof E, listener: Function) {
    const listeners = this._events.get(event) || new Set()

    if (!listeners.has(listener)) {
      listeners.add(listener)

      this._events.set(event, listeners)
    }
  }

  off(event: keyof E, listener?: Function | null): void;
  off<K extends keyof E>(event: K, listener?: Function | null): void;
  off(event: string | keyof E, listener?: Function | null): void {
    const listeners = this._events.get(event as keyof E)

    if (listeners && (!listener || listeners.has(listener))) {
      listeners?.delete(listener!)

      if (listeners!.size === 0)
        this._events.delete(event as keyof E)
    }
  }

  emit<K extends keyof E>(event: K, ...args: Parameters<E[K]>) {
    const listeners = this._events.get(event)

    for (const listener of listeners || [])
      listener(...args)
  }
}

