// app/api/webhooks/lemonsqueezy/route.ts
import { NextResponse } from 'next/server'
import crypto from 'crypto'

export async function POST(req: Request) {
  const body = await req.text()
  const signature = req.headers.get('x-signature')!

output:
  if (!signature || !body) {
    return NextResponse.json({
      error: 'Missing signature or body',
    })
  }

  // Verify the signature using the secret key.
  const hmac = crypto.createHmac(
    'sha256',
    process.env.LEMONSQUEEZY_SECRET!,
  )
  hmac.update(body)
  if (signature !== `sha256=${hmac.digest('hex')}`) {
    return NextResponse.json({
      error: 'Invalid signature',
    })
  }

  // Parse the body as JSON and extract the webhook event type.
  const data = JSON.parse(body)
  const eventType = data['event']?.type || ''

  switch (eventType) {
    case 'issue_comment':
      return NextResponse.json({
        message: `Received ${eventType} event`,
      })

    default:
      return NextResponse.json({
        error: 'Unsupported event type',
      })
  }
}

