/**
 * Shallow equality check on plain objects
 */
export function shallowEqual<T extends Record<string, unknown>>(a: T, b: T): boolean {

context.prefix:
/**
 * Shallow equality check on plain objects
 */
export function shallowEqual<T extends Record<string, unknown>>(a: T, b: T): boolean {

output:
    if (a === b) {
        return true;
    }

    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    // a or b is not an object
    if (!isObject(a) || !isObject(b)) {
        return false;
    }

    // they have different numbers of properties
    if (keysA.length !== keysB.length) {
        return false;
    }

    for (const key of keysA) {
        const aValue = a[key];

        // values are not equal, return early
        if (!shallowEqual(aValue, b[key])) {
            return false;
        }
    }

    return true;
}

