/**
 * Memoize a unary function — caches by argument
 */
export function memoize<A, R>(fn: (arg: A) => R): (arg: A) => R {

output:
    const cache = new Map();

    return (arg: A) => {
        if (!cache.has(arg))
            cache.set(arg, fn(arg));

        return cache.get(arg);
    };
}

