// app/api/posts/[id]/route.ts
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'

const Schema = z.object({ title: z.string().min(1).optional(), body: z.string().optional() })

export async function PATCH(req: Request, { params }: { params: { id: string } }) {

output:
  const { body } = await req.json()

  if (!body) return NextResponse.json({ error: 'No data' }, { status: 400 })

  try {
    await Schema.parse(body)

    // Update the post with the new data
    await prisma.post.update({
      where: { id: params?.id as number },
      data: body,
    })
  } catch (error) {
    return NextResponse.json({ error: 'Invalid data' }, { status: 400 })
  }

  // Return the updated post in the response
  const post = await prisma.post.findUnique({ where: { id: params?.id as number } })

  if (!post) return NextResponse.json({ error: 'Post not found' }, { status: 404 })

  return NextResponse.json(post, { status: 200 })
}

