export async function DELETE(_req: Request, { params }: { params: { id: string } }) {

output:
  const { user } = await auth()

  if (!user) return NextResponse.json({ error: 'Not authenticated.' }, 401)

  try {
    await prisma.post.delete({
      where: {
        id: Number(params?.id),
        authorId: user.id,
      },
    })

    return NextResponse.redirect('/api/posts')
  } catch (error) {
    console.log('Error', error)
    return NextResponse.json({ error: 'Something went wrong.' }, 500)
  }
}

